1	package numeric
2	
3	import (
4		"errors"
5		"strings"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// manualClock 是确定性时钟：每次取值自动推进，保证提交时间严格可排序。
12	type manualClock struct {
13		mu sync.Mutex
14		t  time.Time
15	}
16	
17	func newManualClock() *manualClock {
18		return &manualClock{t: time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)}
19	}
20	
21	func (c *manualClock) Now() time.Time {
22		c.mu.Lock()
23		defer c.mu.Unlock()
24		c.t = c.t.Add(time.Microsecond)
25		return c.t
26	}
27	
28	func openTestStore(t *testing.T) (*Store, *manualClock) {
29		t.Helper()
30		clock := newManualClock()
31		s, err := Open(t.TempDir(), WithClock(clock))
32		if err != nil {
33			t.Fatalf("open: %v", err)
34		}
35		t.Cleanup(func() { _ = s.Close() })
36		return s, clock
37	}
38	
