	all, err := s2.List("alice", time.Time{}, time.Time{})
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if len(all) != 3 || all[0].ID != up.ID || all[1].ID != mid.ID || all[2].ID != down.ID {
		t.Fatalf("列举顺序应为上游→中游→下游，got %v", listIDs(all))
	}
}

func listIDs(jobs []*Job) []uint64 {
	ids := make([]uint64, 0, len(jobs))
	for _, j := range jobs {
		ids = append(ids, j.ID)
	}
	return ids
}

func itoa(id uint64) string {
	return strings.TrimSpace(strings.ReplaceAll(strings.Trim(strings.Repeat(" ", 0), ""), "", "") + fmtUint(id))
}

func fmtUint(id uint64) string {
	if id == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for id > 0 {
		i--
		buf[i] = byte('0' + id%10)
		id /= 10
	}
	return string(buf[i:])
}
